// ─── 2a. Identity & Authentication Service Mock ───────────────────────────────
// Intercepts all imports of the auth service so no real HTTP calls are made.
// Adjust the module path to match your project's actual location.
jest.mock('./src/services/authService', () => {
  // A realistic default user returned by token verification / session lookups.
  const DEFAULT_USER = {
    id: 'test-user-id',
    email: 'testuser@example.com',
    roles: ['user'],
    emailVerified: true,
  };

  return {
    // ── Token verification ──────────────────────────────────────────────────
    /** Simulates a valid, already-decoded JWT. Override per-test as needed. */
    verifyToken: jest.fn().mockResolvedValue({
      sub: DEFAULT_USER.id,
      email: DEFAULT_USER.email,
      roles: DEFAULT_USER.roles,
      iat: Math.floor(Date.now() / 1000) - 60,
      exp: Math.floor(Date.now() / 1000) + 3600,
    }),

    /** Generates a signed JWT string (stubbed — returns a fixed fake token). */
    signToken: jest.fn().mockResolvedValue('mock-jwt-token'),

    // ── Session management ──────────────────────────────────────────────────
    /** Returns the default test user for any session lookup. */
    getSession: jest.fn().mockResolvedValue(DEFAULT_USER),

    /** Simulates a successful session creation. */
    createSession: jest.fn().mockResolvedValue({
      sessionId: 'mock-session-id',
      user: DEFAULT_USER,
      expiresAt: new Date(Date.now() + 3_600_000).toISOString(),
    }),

    /** Simulates a clean session destruction. */
    destroySession: jest.fn().mockResolvedValue({ success: true }),

    // ── User identity ───────────────────────────────────────────────────────
    /** Looks up a user by ID — returns the default user for any ID. */
    getUserById: jest.fn().mockResolvedValue(DEFAULT_USER),

    /** Looks up a user by email. */
    getUserByEmail: jest.fn().mockResolvedValue(DEFAULT_USER),

    // ── Password / credential flows ─────────────────────────────────────────
    /** Always reports credentials as valid in tests. */
    validateCredentials: jest.fn().mockResolvedValue(true),

    /** Returns a bcrypt-style hash stub (no actual hashing). */
    hashPassword: jest.fn().mockResolvedValue('$2b$10$mockedHashValue'),

    /** Skips real bcrypt comparison — always returns true. */
    comparePassword: jest.fn().mockResolvedValue(true),

    // ── OAuth / SSO ─────────────────────────────────────────────────────────
    /** Returns a stubbed OAuth exchange result. */
    exchangeOAuthCode: jest.fn().mockResolvedValue({
      accessToken: 'mock-oauth-access-token',
      refreshToken: 'mock-oauth-refresh-token',
      user: DEFAULT_USER,
    }),

    /** Refreshes an OAuth token — returns a new fake access token. */
    refreshOAuthToken: jest.fn().mockResolvedValue({
      accessToken: 'mock-oauth-access-token-refreshed',
    }),

    // ── Permission / RBAC ───────────────────────────────────────────────────
    /** Grants every permission check by default. */
    hasPermission: jest.fn().mockResolvedValue(true),

    /** Returns the roles array from DEFAULT_USER. */
    getUserRoles: jest.fn().mockResolvedValue(DEFAULT_USER.roles),
  };
});

// Helper: call this in a test to simulate an unauthenticated or forbidden state.
// Usage:
//   const authService = require('./src/services/authService');
//   mockAuthAsUnauthorized(authService);
global.mockAuthAsUnauthorized = (authService) => {
  authService.verifyToken.mockRejectedValueOnce(
    Object.assign(new Error('Token expired or invalid'), { code: 'AUTH_UNAUTHORIZED' })
  );
  authService.getSession.mockResolvedValueOnce(null);
};

// Helper: override the authenticated user for a single test.
// Usage:
//   mockAuthAsUser(authService, { id: 'admin-1', roles: ['admin'] });
global.mockAuthAsUser = (authService, userOverrides = {}) => {
  const user = {
    id: 'test-user-id',
    email: 'testuser@example.com',
    roles: ['user'],
    emailVerified: true,
    ...userOverrides,
  };
  authService.getSession.mockResolvedValueOnce(user);
  authService.getUserById.mockResolvedValueOnce(user);
  authService.verifyToken.mockResolvedValueOnce({
    sub: user.id,
    email: user.email,
    roles: user.roles,
    iat: Math.floor(Date.now() / 1000) - 60,
    exp: Math.floor(Date.now() / 1000) + 3600,
  });
};

